[归一化后的问题]
2026-08 的日期维表有多少天？

[已审查的查询计划]
{
  "assets": [
    {
      "asset": "dim_date",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "dim_date.year = 2026",
    "dim_date.month = 8"
  ],
  "grain": "day（日历维表行粒度）",
  "limit": 1,
  "metrics": [
    {
      "caliber": "日历维表的存量天数：COUNT(*)，不带任何默认时间谓词，需显式加月份筛选谓词",
      "name": "day_cnt"
    }
  ],
  "order_by": [],
  "output_columns": [
    "day_cnt"
  ],
  "time_range": {
    "end": "2026-08-31",
    "start": "2026-08-01"
  }
}

